function UIBattleEndDirectional:SetPanelInfo()
    xTry(function()
        local questId = BattleEndMgr.questId
        self:SetQuestLevelIcon(questId)
        local questPassType = BattleEndMgr.passType
        if not IsNull(self.Node_Jump) then
            KTool.SetActive(self.Node_Jump.gameObject, questPassType < 1)
            KTool.SetActive(self.Root_Score.gameObject, questPassType >= 1)
        end
    end)
end

function UIBattleEndDirectional:SetQuestLevelIcon(questId)
    xTry(function() 
        local questData = QuestConfMgr:GetInstance():GetQuestVoById(questId)
        local DirectionalFightComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DirectionalFightComponent)
        local pathInDirDialog = DirectionalFightComponent:GetLevelIconPath(true, questData.regionLevel)
        local pathInDirEnd = string.format("Arts/Icons/Directional/%s.png", string.lower(io.pathInfo(pathInDirDialog).basename))
        CfUtils.FillImage(self.ImgLevel, pathInDirEnd)
    end)
end

return UIBattleEndDirectional